class _Interrupted:
    """The replay agent, raising `KeyboardInterrupt` on call number `at` of one kind of call.

    `where` is `learn`, `train_act` (an exploring `act`, which only training makes) or
    `eval_act` (a greedy `act`, which only evaluation makes).
    """

    def __init__(self, at: int, where: str = "learn") -> None:
        codec = _codec()
        agents = codec.fake("core.Agent")
        self.inner = agents.ReplayAgent(
            codec.sample("core.Agent", AGENT_CASE, agents.AgentRecording)
        )
        self.at = at
        self.where = where
        self.counts = {"learn": 0, "train_act": 0, "eval_act": 0}

    @property
    def learns(self) -> int:
        return self.counts["learn"]

    def _tick(self, kind: str) -> None:
        self.counts[kind] += 1
        if kind == self.where and self.counts[kind] >= self.at:
            raise KeyboardInterrupt

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        self._tick("train_act" if explore else "eval_act")
        action: np.ndarray = self.inner.act(obs, explore=explore)
        return action

    def learn(self, t: Transition) -> None:
        self._tick("learn")
        self.inner.learn(t)

